-- PostgreSQL：查看实际执行计划与耗时
EXPLAIN ANALYZE
SELECT id, email FROM users WHERE lower(email) = 'a@b.com';
-- 输出若含 "Seq Scan on users"，说明逐行扫描

-- 原因：普通索引建在 email 上，但条件对列套了函数
-- 方案一：建表达式索引，与查询写法保持一致
CREATE INDEX idx_users_lower_email ON users (lower(email));

-- 方案二：前缀匹配可用 B-tree（需 text_pattern_ops 或 C 排序规则）
CREATE INDEX idx_users_email_prefix ON users (email text_pattern_ops);
EXPLAIN SELECT id FROM users WHERE email LIKE 'abc%';

-- 更新统计信息，避免优化器误判
ANALYZE users;

CREATE TABLE orgs (
  id bigint PRIMARY KEY
);

CREATE TABLE projects (
  id     bigint PRIMARY KEY,
  org_id bigint NOT NULL
    REFERENCES orgs(id) ON DELETE CASCADE   -- 删组织连带删项目
);

CREATE TABLE tasks (
  id          bigint PRIMARY KEY,
  project_id  bigint NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  assignee_id bigint REFERENCES users(id) ON DELETE SET NULL  -- 人走了任务保留
);

-- PostgreSQL 不会自动给外键列建索引，需手动补上
CREATE INDEX ON projects (org_id);
CREATE INDEX ON tasks (project_id);

-- 大表加外键：先 NOT VALID 再校验，减少锁时间
ALTER TABLE tasks ADD CONSTRAINT tasks_creator_fk
  FOREIGN KEY (creator_id) REFERENCES users(id) NOT VALID;
ALTER TABLE tasks VALIDATE CONSTRAINT tasks_creator_fk;

ALTER TABLE posts ADD COLUMN deleted_at timestamptz;

-- 删除 = 打标记
UPDATE posts SET deleted_at = now() WHERE id = 42;

-- 视图统一过滤，业务代码查视图而不是原表
CREATE VIEW active_posts AS
  SELECT * FROM posts WHERE deleted_at IS NULL;

-- 唯一约束只针对有效行
CREATE UNIQUE INDEX posts_slug_active_uniq
  ON posts (slug) WHERE deleted_at IS NULL;

-- 常用查询的索引也加同样条件，体积更小
CREATE INDEX posts_author_active_idx
  ON posts (author_id, created_at) WHERE deleted_at IS NULL;

-- 定期清理：保留 30 天后物理删除（分批执行）
DELETE FROM posts
WHERE id IN (SELECT id FROM posts
             WHERE deleted_at < now() - interval '30 days' LIMIT 1000);

-- 自增：PostgreSQL 推荐 IDENTITY（SQL 标准），比 SERIAL 更规范
CREATE TABLE orders (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  created_at timestamptz NOT NULL DEFAULT now()
);

-- UUID：用原生 uuid 类型（16 字节），不要存成 varchar
-- gen_random_uuid() 生成 v4，PostgreSQL 13 起内置
CREATE TABLE files (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL
);

-- 混合方案：内部 bigint 主键做关联，对外暴露 UUID
CREATE TABLE users (
  id        bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  public_id uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(),
  email     text NOT NULL
);
-- 需要 UUIDv7 时，可在应用层生成（各语言有成熟库），
-- 或确认所用数据库版本是否已内置 v7 函数

import base64, json

def encode_cursor(row):
    data = {"t": row["created_at"].isoformat(), "id": row["id"]}
    return base64.urlsafe_b64encode(json.dumps(data).encode()).decode()

def decode_cursor(cursor):
    return json.loads(base64.urlsafe_b64decode(cursor.encode()))

SQL_FIRST = """SELECT id, created_at, title FROM posts
  ORDER BY created_at DESC, id DESC LIMIT %(n)s"""
SQL_NEXT = """SELECT id, created_at, title FROM posts
  WHERE (created_at, id) < (%(t)s, %(id)s)   -- 行值比较
  ORDER BY created_at DESC, id DESC LIMIT %(n)s"""

def list_posts(cur, limit=20, cursor=None):
    params = {"n": limit + 1}               # 多取一条判断 has_more
    if cursor:
        params.update(decode_cursor(cursor))
    cur.execute(SQL_NEXT if cursor else SQL_FIRST, params)
    rows = cur.fetchall()                   # 假设使用 dict_row 行工厂
    has_more = len(rows) > limit
    rows = rows[:limit]
    nxt = encode_cursor(rows[-1]) if has_more else None
    return {"data": rows, "next_cursor": nxt}
