import express from "express";

const app = express();
const v1 = express.Router();
const v2 = express.Router();

// v1：返回 name 单字段（已弃用）
v1.get("/users/:id", (req, res) => {
  res.set("Deprecation", "@1767225600"); // RFC 9745：弃用起始时间戳
  res.set("Sunset", "Thu, 01 Jul 2027 00:00:00 GMT");
  res.set("Link", '</v2/users>; rel="successor-version"');
  res.json({ id: req.params.id, name: "Ada Lovelace" });
});

// v2：破坏性变更，拆为两个字段
v2.get("/users/:id", (req, res) => {
  res.json({ id: req.params.id, firstName: "Ada", lastName: "Lovelace" });
});

app.use("/v1", v1);
app.use("/v2", v2);
app.listen(3000);

# ---- Nginx：全局较小，上传接口单独放宽 ----
http {
    client_max_body_size 1m;            # 默认值即 1m
    large_client_header_buffers 4 8k;   # 限制请求头
    server {
        location /api/upload {
            client_max_body_size 20m;   # 仅上传接口放宽
        }
    }
}

// ---- Express：应用层再限制一次 ----
const express = require("express");
const app = express();
app.use(express.json({ limit: "100kb" }));    // 默认即 100kb
app.use(express.urlencoded({ limit: "100kb", extended: false }));
app.use((err, req, res, next) => {
  if (err.type === "entity.too.large") return res.status(413).end();
  next(err);
});

http {
    gzip on;
    gzip_comp_level 5;            # 1-9，在线压缩取中间值
    gzip_min_length 1024;         # 太小的响应不压缩
    gzip_vary on;                 # 自动加 Vary: Accept-Encoding
    gzip_proxied any;
    gzip_types text/css application/javascript
               application/json image/svg+xml;  # text/html 默认已包含

    # 构建时生成的 .gz 文件直接发送，不再实时压缩
    gzip_static on;

    # Brotli 需第三方模块 ngx_brotli，可用时再启用：
    # brotli on;
    # brotli_static on;
}

